import {FLOORPLANS} from './mall-plans.js?v=23.0.0';
import {CENTER_DIRECTORIES} from './full-center-data.js?v=23.0.0';
export const CAMPUS_REVISION=10;
export const normalizeName=s=>String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'');
const aliases={lv:['louisvuitton'],ysl:['saintlaurent'],tory:['toryburch'],levis:['levis'],bathbody:['bathbodyworks'],hm:['hm'],nike:['nike','nikefactorystore'],oldnavy:['oldnavy','oldnavyoutlet'],nordstrom:['nordstrom'],bottega:['bottegaveneta'],hermes:['hermesparis','hermes'],cartier:['cartier'],tiffany:['tiffanyco'],apple:['apple'],newbalance:['newbalance']};
export function matchingTenant(mall,id,stores){const st=stores.find(s=>s.id===id),names=aliases[id]||[normalizeName(st?.name||id)];return (CENTER_DIRECTORIES[mall]?.tenants||[]).find(t=>names.some(n=>normalizeName(t.name)===n||normalizeName(t.name)===n+'outlet'||normalizeName(t.name)===n+'factorystore'));}
export function tenantFloor(mall,t){if(typeof t?.floor==='number')return Math.max(0,t.floor-1);const level=String(t?.floor??'').toLowerCase();if(mall==='delamo')return /lower/.test(level)?0:/upper/.test(level)?2:1;if(mall==='island')return /lower/.test(level)?1:/upper/.test(level)?2:/roof/.test(level)?3:0;if(mall==='beverly')return /8/.test(level)?3:/7/.test(level)?2:/6/.test(level)?1:0;if(/upper/.test(level))return 1;const n=level.match(/(?:level|floor)\s*([123])/);return n?Math.min(Number(n[1])-1,FLOORPLANS[mall].levels.length-1):0;}
export function gameStoreFloor(mall,id,stores=[]){if(id.startsWith(mall.id+'-tenant-')){const key=id.slice((mall.id+'-tenant-').length),t=CENTER_DIRECTORIES[mall.id].tenants.find(t=>(t.key||normalizeName(t.name))===key);if(t)return tenantFloor(mall.id,t);}const tenant=matchingTenant(mall.id,id,stores);if(tenant?.floor)return tenantFloor(mall.id,tenant);const ids=[...new Set(mall.sections.flatMap(d=>d.stores).filter(id=>!id.includes('-tenant-')))],index=ids.indexOf(id),count=FLOORPLANS[mall.id].levels.length;if(mall.id==='island')return 0;if(mall.id==='delamo')return 1;if(mall.id==='southcoast')return ['lv','prada','bottega','cartier'].includes(id)?1:0;if(mall.id==='beverly')return 2;return count>1?index%Math.min(2,count):0;}
function makeGraph(nodes,links,width=200){return {nodes:nodes.map(([x,y,label],i)=>({id:String(i),x,y,label})),halls:links.map(([a,b])=>({a:String(a),b:String(b),width}))};}
const southNodes=[[700,700,'Home wing · A'],[580,1150,'West Elm wing · B'],[900,1150,'Crate & Barrel wing · C'],[700,1450,'West entrance'],[1700,950,'Garden Terrace'],[2050,650,'Nordstrom Court · D / G'],[2050,1100,'Jewel Court · E / H'],[2050,1550,'Macy’s Men wing · F / I'],[2500,1100,'Central gallery · K'],[2500,1550,'South gallery · L'],[2950,650,'North entrance · M / Q'],[2950,1100,'Carousel Court · N'],[2950,1550,'East gallery · O'],[3350,1100,'Bristol gallery · R'],[3350,1550,'Bloomingdale’s wing · S'],[3350,2000,'South-east court · T'],[2950,2000,'Dining wing · P'],[2350,2050,'Macy’s Men court · J']];
const southLinks=[[0,1],[0,2],[1,3],[2,3],[5,6],[6,4],[6,7],[6,8],[8,11],[11,13],[7,9],[9,12],[12,14],[13,14],[14,15],[15,16],[16,12],[7,17],[17,9],[10,11],[11,12]];
export function campusPlan(mall,floor=0){const p=FLOORPLANS[mall.id],width=mall.id==='southcoast'?4200:3600,height=mall.id==='southcoast'?2800:2700;let nodes=p.nodes.map(n=>[n.x*3,n.y*3,n.label]),links=p.edges.map(e=>[Number(e.a),Number(e.b)]),hallWidth=120;
 if(mall.id==='island'&&floor===0){nodes=[[1360,760,'Nordstrom Court'],[1850,600,'North Court'],[2670,970,'Neiman Marcus Court'],[1368,1803,'Macy’s Court'],[2315,909,'Bloomingdale’s Court'],[1860,2050,'South Court'],[950,1450,'West Court'],[1850,1430,'Koi Pond'],[2420,1530,'Iris Fountain'],[1830,2400,'Coastal Entrance']];links=[[0,1],[1,4],[4,2],[2,8],[8,5],[5,3],[3,6],[6,0],[0,7],[7,8],[7,3],[7,4],[5,9]];}
 if(mall.id==='southcoast'){nodes=southNodes.map((n,i)=>i<4?[[650,600,n[2]],[350,1250,n[2]],[970,1250,n[2]],[650,1800,n[2]]][i]:n);links=southLinks.slice();if(floor===1)links.push([2,4]);if(floor===0){nodes=[...nodes,[700,160,'South Coast Plaza Village'],[1050,160,'Bear Street Gallery']];links.push([0,18],[18,19]);}if(floor===2){nodes=[nodes[0],nodes[1],nodes[2],nodes[5],[2050,1350,'Nordstrom upper gallery']];links=[[0,1],[0,2],[1,2],[3,4]];}hallWidth=120;}
 if(mall.id==='delamo'&&floor===0){const chosen=[3,4,5,6,9];nodes=chosen.map(i=>nodes[i]);links=[[0,1],[0,4],[4,1],[2,3],[1,2]];}
 if(mall.id==='island'&&floor>0){const places=(CENTER_DIRECTORIES.island?.tenants||[]).filter(t=>tenantFloor('island',t)===floor&&Number.isFinite(t.x)&&Number.isFinite(t.y));if(places.length){const xs=places.map(t=>t.x*width),ys=places.map(t=>t.y*height),cx=(Math.min(...xs)+Math.max(...xs))/2,cy=(Math.min(...ys)+Math.max(...ys))/2;const halfSpan=Math.max(170,places.length*42);nodes=[[cx-halfSpan,cy,'Gallery west'],[cx,cy,'Upper court'],[cx+halfSpan,cy,'Gallery east']];links=[[0,1],[1,2]];}else{nodes=[[1450,1350,'Department gallery'],[1750,1350,'Dining gallery']];links=[[0,1]];}hallWidth=116;}
 if(mall.id==='century'&&floor===2){nodes=[[1800,1200,'Upper dining landing'],[2110,1200,'Level 3 gallery'],[2350,1350,'Upper terrace']];links=[[0,1],[1,2]];}
 if(mall.id==='beverly'&&floor===3){nodes=[[1320,1050,'Upper service landing'],[1710,1050,'Level 8 terrace'],[1950,1170,'Atrium overlook']];links=[[0,1],[1,2]];}
 if(mall.id==='beverly'&&floor===0){nodes=[[1000,1950,'Street entrance'],[1750,1950,'San Vicente promenade'],[2500,1950,'La Cienega entrance']];links=[[0,1],[1,2]];}
 const graph=makeGraph(nodes,links,hallWidth),outdoor=['orange','citadel','spectrum','desert','island','century'].includes(mall.id),courts=graph.nodes.map(n=>({...n,radius:graph.halls.filter(e=>e.a===n.id||e.b===n.id).length>2?112:100}));
 const escalators=[];if(p.levels.length>1){const indexes=mall.id==='southcoast'?(floor===2?[0,3]:[2,5,11]):mall.id==='island'&&floor>0?[1]:floor===2?[0]:[Math.min(2,nodes.length-1),Math.min(nodes.length-1,5)];[...new Set(indexes)].forEach((index,i)=>{const n=graph.nodes[index],id=mall.id==='southcoast'?(index===0||index===2?'west':index===3||index===5?'nordstrom':'east'):'core-'+i;escalators.push({id,node:n.id,x:n.x-32,y:n.y-44,width:65,height:95,landing:{x:n.x+90,y:n.y+20},floors:mall.id==='southcoast'&&id==='east'?[0,1]:Array.from({length:p.levels.length},(_,j)=>j)});});}
 return {...graph,width,height,outdoor,courts,escalators,source:p.source,floor,completeFloor:floor<2&&!(mall.id==='island'&&floor>0),family:mall.id,zones:graph.nodes};
}
export function zoneOf(layout,point){return layout.campus.nodes.reduce((best,n)=>Math.hypot(n.x-point.x,n.y-point.y)<Math.hypot(best.x-point.x,best.y-point.y)?n:best,layout.campus.nodes[0]);}
